<?php
declare(strict_types=1);
namespace Baloot\Game;
final class Rules {
 public const SUITS=['S','H','D','C'];public const RANKS=['7','8','9','J','Q','K','10','A'];private const SUN=['7','8','9','J','Q','K','10','A'];private const TRUMP=['7','8','Q','K','10','A','9','J'];private const SP=['A'=>11,'10'=>10,'K'=>4,'Q'=>3,'J'=>2,'9'=>0,'8'=>0,'7'=>0];private const TP=['J'=>20,'9'=>14,'A'=>11,'10'=>10,'K'=>4,'Q'=>3,'8'=>0,'7'=>0];
 public static function team(int $s):int{return $s%2;}public static function next(int $s):int{return Seating::counterClockwiseSeat($s);}
 public static function deck():array{$d=[];foreach(self::SUITS as $s)foreach(self::RANKS as $r)$d[]=['suit'=>$s,'rank'=>$r,'id'=>$s.$r];return $d;}
 public static function shuffle(array $a):array{for($i=count($a)-1;$i>0;$i--){$j=random_int(0,$i);[$a[$i],$a[$j]]=[$a[$j],$a[$i]];}return $a;}
 public static function create(array $names=['ضيف','ضيف','ضيف','ضيف']):array{return ['phase'=>'dealing','players'=>array_map(fn($n,$i)=>['name'=>$n,'seat'=>$i,'bot'=>false],$names,array_keys($names)),'hands'=>[[],[],[],[]],'scores'=>[0,0],'dealScores'=>[],'dealer'=>0,'turn'=>0,'round'=>1,'upCard'=>null,'contract'=>null,'trick'=>[],'tricks'=>[],'tricksWon'=>[0,0],'history'=>[],'lastWinner'=>null,'auctionPasses'=>0,'auctionOrder'=>[],'postPurchase'=>null,'projectClaims'=>[[],[],[],[]],'projectOptions'=>[[],[],[],[]],'projectDeclared'=>[false,false,false,false],'balotClaims'=>[]];}
 public static function deal(array &$g):void{$d=self::shuffle(self::deck());for($i=0;$i<4;$i++)$g['hands'][$i]=array_slice($d,$i*5,5);$g['upCard']=$d[20];$g['stock']=array_slice($d,21);$g['phase']='auction1';$g['turn']=self::next($g['dealer']);$g['auctionPasses']=0;$g['auctionOrder']=array_reduce(range(0,3),function(array $order,int $i)use($g):array{$order[]=$i===0?$g['turn']:self::next($order[$i-1]);return $order;},[]);$g['contract']=null;$g['trick']=[];$g['tricks']=[];$g['tricksWon']=[0,0];$g['history']=[];$g['qaidResult']=null;$g['balotClaims']=[];$g['projectClaims']=[[],[],[],[]];$g['projectOptions']=[[],[],[],[]];$g['projectDeclared']=[false,false,false,false];}
 public static function rank(array $c,?string $trump=null):int{$o=$trump&&$c['suit']===$trump?self::TRUMP:self::SUN;return array_search($c['rank'],$o,true);}
 public static function points(array $c,array $k):int{return (($k['type']==='hokum'&&$c['suit']===$k['trump'])?self::TP:self::SP)[$c['rank']];}
 public static function winner(array $t,array $k):int{$lead=$t[0]['card']['suit'];$best=$t[0];foreach(array_slice($t,1) as $p){$a=$p['card'];$b=$best['card'];$at=$k['type']==='hokum'&&$a['suit']===$k['trump'];$bt=$k['type']==='hokum'&&$b['suit']===$k['trump'];if($at&&!$bt)$best=$p;elseif($at===$bt){if($at){if(self::rank($a,$k['trump'])>self::rank($b,$k['trump']))$best=$p;}elseif($a['suit']===$lead&&$b['suit']!==$lead)$best=$p;elseif($a['suit']===$lead&&$b['suit']===$lead&&self::rank($a)>self::rank($b))$best=$p;}}return $best['seat'];}
 public static function legal(array $h,array $t,array $k,int $seat):array{$tr=$k['type']==='hokum'?array_values(array_filter($h,fn($c)=>$c['suit']===$k['trump'])):[];$non=$k['type']==='hokum'?array_values(array_filter($h,fn($c)=>$c['suit']!==$k['trump'])):$h;if(!$t)return !empty($k['restricted'])&&$seat!==($k['lastWinnerSeat']??null)&&$tr&&$non?$non:$h;$lead=$t[0]['card']['suit'];$follow=array_values(array_filter($h,fn($c)=>$c['suit']===$lead));if($k['type']==='sun')return $follow?:$h;if($follow)return $follow;if(!$tr)return $h;$winner=self::winner($t,$k);if(self::team($winner)===self::team($seat))return !empty($k['restricted'])&&$non?$non:$h;$table=array_values(array_filter($t,fn($p)=>$p['card']['suit']===$k['trump']));if($table){$high=max(array_map(fn($p)=>self::rank($p['card'],$k['trump']),$table));$over=array_values(array_filter($tr,fn($c)=>self::rank($c,$k['trump'])>$high));if($over)return $over;}return $tr;}
 public static function play(array &$g,int $seat,string $id):void{if($g['phase']!=='playing'||$g['turn']!==$seat)throw new \DomainException('ليس دورك في اللعب');$idx=null;foreach($g['hands'][$seat] as $i=>$c)if($c['id']===$id){$idx=$i;break;}if($idx===null)throw new \DomainException('الورقة غير موجودة في يدك');$card=$g['hands'][$seat][$idx];$allowed=self::legal($g['hands'][$seat],$g['trick'],$g['contract'],$seat);$lead=$g['trick'][0]['card']['suit']??null;$violation=!empty($g['qaidEnabled'])&&$lead!==null&&count(array_filter($g['hands'][$seat],fn($c)=>$c['suit']===$lead))>0&&$card['suit']!==$lead;if(!in_array($id,array_column($allowed,'id'),true)&&!(($g['qaidEnabled']??false)&&$violation))throw new \DomainException('هذه الورقة مخالفة لقواعد اللعب');if($g['contract']['type']==='hokum'&&$card['suit']===$g['contract']['trump']&&in_array($card['rank'],['K','Q'],true)){$other=$card['rank']==='K'?'Q':'K';$prior=false;$claimed=false;foreach($g['history'] as $h)if($h['seat']===$seat&&$h['card']['suit']===$g['contract']['trump']&&$h['card']['rank']===$other)$prior=true;foreach($g['balotClaims'] as $b)if($b['seat']===$seat)$claimed=true;if($prior&&!$claimed)$g['balotClaims'][]=['type'=>'belot','strength'=>0,'high'=>0,'suit'=>$g['contract']['trump'],'seat'=>$seat,'team'=>self::team($seat),'label'=>'بلوت'];}$g['doubleWindow']=false;$g['contract']['lastWinnerSeat']=$g['lastWinner'];array_splice($g['hands'][$seat],$idx,1);$g['trick'][]=['seat'=>$seat,'card'=>$card];$g['history'][]=['seat'=>$seat,'card'=>$card,'trickIndex'=>count($g['tricks']),'leadSuit'=>$lead,'violation'=>$violation];if(count($g['trick'])<4){$g['turn']=self::next($seat);return;}$w=self::winner($g['trick'],$g['contract']);$pts=array_sum(array_map(fn($p)=>self::points($p['card'],$g['contract']),$g['trick']));$team=self::team($w);$g['tricksWon'][$team]++;$g['tricks'][]=['plays'=>$g['trick'],'winner'=>$w,'team'=>$team,'points'=>$pts];$g['lastWinner']=$w;$g['contract']['lastWinnerSeat']=$w;$g['trick']=[];$g['turn']=$w;if(!array_filter($g['hands'],fn($x)=>count($x)>0))self::finishRound($g);}
 public static function finishRound(array &$g):void{$raw=[0,0];foreach($g['tricks'] as $t)$raw[$t['team']]+=$t['points'];$last=self::team((int)$g['lastWinner']);$raw[$last]+=10;$g['lastRaw']=$raw;$r=Scoring::score($raw,$g['contract'],[...$g['projectClaims'],$g['balotClaims']],$g['dealer'],$g['tricksWon']);$g['lastScoring']=$r;$g['lastAwarded']=$r['awarded'];$g['phase']='roundEnd';$g['dealScores'][]=['round'=>$g['round'],'contract'=>$g['contract'],'raw'=>$raw,'awarded'=>$r['awarded'],'tricksWon'=>$g['tricksWon'],'buyerFailed'=>$r['buyerFailed'],'projects'=>$r['projects']];if($r['coffee']){$g['scores'][$r['roundWinner']]=max($g['scores'][$r['roundWinner']],152);$g['phase']='gameEnd';$g['winner']=$r['roundWinner'];return;}$g['scores'][0]+=$r['awarded'][0];$g['scores'][1]+=$r['awarded'][1];if(($g['scores'][0]>=152||$g['scores'][1]>=152)&&$g['scores'][0]!==$g['scores'][1]){$g['phase']='gameEnd';$g['winner']=$g['scores'][0]>$g['scores'][1]?0:1;}}
 public static function nextRound(array &$g):void{if(!in_array($g['phase'],['roundEnd','redeal'],true))throw new \DomainException('لا يمكن بدء توزيعة جديدة الآن');$g['dealer']=self::next($g['dealer']);$g['round']++;self::deal($g);}
}